  const legacyCashId=savedData.caixas[0]?.id||'caixa-principal';
  savedData.vendas.forEach(record=>record.caixaId||=legacyCashId);
  savedData.despesas.forEach(record=>record.caixaId||=legacyCashId);
  savedData.preVendas.forEach(record=>record.caixaId||=legacyCashId);
  savedData.servicos.forEach(record=>record.caixaId||=legacyCashId);
  savedData.pagamentos.forEach(record=>record.caixaId||=savedData.vendas.find(sale=>sale.id===record.saleId)?.caixaId||legacyCashId);
  savedData.pagamentosDespesas.forEach(record=>record.caixaId||=savedData.despesas.find(expense=>expense.id===record.expenseId)?.caixaId||legacyCashId);
