  const emojiDefaults={'Bala de Ninho':'🍬','Mousse':'🍮','Cone Ferrero':'🍫','Refrigerante lata':'🥤','Leite em pó':'🥛','Leite condensado':'🥫','Açúcar':'🧂','Embalagem':'📦','Chocolate':'🍫'};
