  function listRange(){const startValue=main.querySelector('.list-start')?.value,endValue=main.querySelector('.list-end')?.value;return {start:startValue?new Date(startValue+'T00:00:00'):null,end:endValue?new Date(endValue+'T23:59:59'):null}}
