  function parseExpenseItems(values){return Object.keys(values).filter(key=>key.startsWith('itemProduto')).map(key=>key.replace('itemProduto','')).map(i=>({produto:values[`itemProduto${i}`],quantidade:+values[`itemQtd${i}`]||0,custo:+values[`itemCusto${i}`]||0})).filter(item=>item.produto&&item.quantidade>0)}
